CREATE TABLE IF NOT EXISTS projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), opportunity_id UUID REFERENCES opportunities(id), name TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'planned', start_date DATE, target_end_date DATE, actual_end_date DATE, budget NUMERIC(12,2) NOT NULL DEFAULT 0, estimated_cost NUMERIC(12,2) NOT NULL DEFAULT 0, actual_cost NUMERIC(12,2) NOT NULL DEFAULT 0, progress_percent INT NOT NULL DEFAULT 0 CHECK (progress_percent >= 0 AND progress_percent <= 100), project_manager_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_milestones (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, due_date DATE, completed_at TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, milestone_id UUID REFERENCES project_milestones(id) ON DELETE SET NULL, title TEXT NOT NULL, description TEXT, status TEXT NOT NULL DEFAULT 'todo', priority TEXT NOT NULL DEFAULT 'medium', assigned_user_id UUID REFERENCES users(id), due_date DATE, estimated_hours NUMERIC(8,2), actual_hours NUMERIC(8,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS project_time_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, task_id UUID REFERENCES project_tasks(id) ON DELETE SET NULL, user_id UUID NOT NULL REFERENCES users(id), hours NUMERIC(8,2) NOT NULL, billable BOOLEAN NOT NULL DEFAULT true, entry_date DATE NOT NULL, notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
